"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["63187"],{65698(e){e.exports=JSON.parse('{"id":"FIN-940","slug":"total-addressable-market","term":"Total Addressable Market (TAM)","also_known_as":["TAM"],"difficulty":"Intermediate","definition":"Total addressable market (TAM) is the total revenue opportunity available for a product or service if it captured 100% of its potential market.","explanation":["TAM is used to estimate the maximum size of an opportunity, especially by start-ups, investors and companies planning new products. It answers the question: how big could this business become if everyone who might buy the product did so?","TAM can be estimated from the top down, using industry reports and market data, or from the bottom up, multiplying the number of potential customers by the average revenue per customer. For example, if there are 2 million small businesses in a country that could use a particular accounting software, and each would pay 500 a year, the TAM is 1 billion a year.","TAM is often discussed alongside two narrower measures. The serviceable addressable market is the portion of TAM that the company\'s product and business model can realistically serve. The serviceable obtainable market is the share the company can realistically capture in the near term.","Investors like large TAMs because they suggest room for significant growth. However, TAM estimates are frequently inflated in pitches. A credible TAM is based on realistic assumptions about who would actually buy the product and how much they would pay."],"note":"","total":1500,"prev":{"slug":"too-big-to-fail","term":"Too Big to Fail"},"next":{"slug":"total-factor-productivity","term":"Total Factor Productivity"}}')}}]);